const MODELO = 'claude-haiku-5-5';
const LIMITE_PERGUNTA = 1000;
const LIMITE_HISTORICO = 6;

const PROMPT_PADRAO = [
  'Você é a GSA IA, assistente do projeto GSA - Grana Sem Aperto, um site de educação financeira para jovens.',
  'Responda sempre em português do Brasil, de forma educativa, clara, acolhedora e simples. Explique finanças para iniciantes.',
  'Nunca prometa ganhos. Nunca aja como consultora financeira profissional. Quando o assunto for investimento, ações, mercado atual ou notícias, deixe claro no alerta que a resposta é educativa e não é recomendação financeira.',
  'Se a pergunta depender de dados do momento, diga com honestidade que você explica de forma geral, sem pesquisa em tempo real.',
  'Você responde temas de educação financeira, consumo consciente, orçamento, dívidas, crédito, investimentos para iniciantes, riscos, planejamento, bancos, impostos básicos, seguros, organização financeira e dúvidas sobre o próprio site GSA.',
  'Se a pergunta fugir disso, explique com gentileza que a GSA IA é focada em educação financeira e sugira um tema parecido que você pode explicar.',
  'Formato da resposta: titulo curto; resumo em uma frase; explicacao clara e didática em até 4 frases; exatamente 3 pontos_chave curtos; alerta curto ou vazio. Não use markdown e não gere exercícios.'
].join('\n');

const SCHEMA_CHAT = {
  type: 'object',
  properties: {
    titulo: { type: 'string' },
    resumo: { type: 'string' },
    explicacao: { type: 'string' },
    pontos_chave: { type: 'array', items: { type: 'string' } },
    alerta: { type: 'string' }
  },
  required: ['titulo', 'resumo', 'explicacao', 'pontos_chave', 'alerta'],
  additionalProperties: false
};

const SCHEMA_QUIZ = {
  type: 'object',
  properties: {
    titulo: { type: 'string' },
    descricao: { type: 'string' },
    perguntas: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          pergunta: { type: 'string' },
          opcoes: { type: 'array', items: { type: 'string' } },
          correta: { type: 'integer' },
          explicacao: { type: 'string' }
        },
        required: ['pergunta', 'opcoes', 'correta', 'explicacao'],
        additionalProperties: false
      }
    }
  },
  required: ['titulo', 'descricao', 'perguntas'],
  additionalProperties: false
};

const texto = (valor) => (typeof valor === 'string' ? valor.trim() : '');
const corpo = $json.body ?? $json;
const modo = texto(corpo.mode ?? corpo.modo).toLowerCase() === 'quiz' ? 'quiz' : 'chat';

if (modo === 'quiz') {
  const modulo = texto(corpo.module ?? corpo.modulo ?? corpo.topic);
  if (!modulo) {
    return { json: { valido: false, modo, erro: 'O campo "module" é obrigatório para gerar quiz.' } };
  }
  const curso = texto(corpo.course ?? corpo.curso) || 'Cursos GSA';
  const contextoModulo = texto(corpo.module_context ?? corpo.contexto_modulo ?? corpo.contexto) || 'Use o nome do módulo como base principal.';
  const pedida = Number(corpo.count ?? corpo.quantidade ?? 8);
  const quantidade = Number.isFinite(pedida) ? Math.max(8, Math.min(10, Math.round(pedida))) : 8;
  const evitar = Array.isArray(corpo.avoid_questions)
    ? corpo.avoid_questions.map((item) => texto(String(item))).filter(Boolean).slice(-30)
    : [];

  const instrucoes = [
    'Módulo: ' + modulo,
    'Curso: ' + curso,
    'Contexto do módulo: ' + contextoModulo,
    'Quantidade de perguntas: ' + quantidade,
    'Perguntas para não repetir: ' + (evitar.length ? evitar.join(' | ') : 'nenhuma ainda'),
    '',
    'Regras:',
    '- Gere exatamente ' + quantidade + ' perguntas sobre o módulo.',
    '- Cada pergunta tem exatamente 4 opções, e correta é o índice da certa, de 0 a 3.',
    '- Misture nível fácil e intermediário, sempre em linguagem simples.',
    '- Não repita perguntas da lista acima nem faça perguntas muito parecidas entre si.',
    '- A explicacao de cada pergunta tem uma frase curta.'
  ].join('\n');

  return {
    json: {
      valido: true,
      modo,
      quantidade,
      modulo,
      pedido: {
        model: MODELO,
        max_tokens: 8000,
        system: 'Você é a GSA IA do projeto Grana Sem Aperto. Crie quizzes curtos, didáticos e em português do Brasil para jovens que estão aprendendo educação financeira.',
        messages: [{ role: 'user', content: instrucoes }],
        output_config: { effort: 'low', format: { type: 'json_schema', schema: SCHEMA_QUIZ } }
      }
    }
  };
}

const pergunta = texto(corpo.message ?? corpo.mensagem ?? corpo.pergunta).slice(0, LIMITE_PERGUNTA);
if (!pergunta) {
  return { json: { valido: false, modo, erro: 'O campo "mensagem" é obrigatório.' } };
}

const historico = [];
const historicoBruto = Array.isArray(corpo.historico) ? corpo.historico.slice(-LIMITE_HISTORICO) : [];
for (const item of historicoBruto) {
  if (!item || (item.role !== 'user' && item.role !== 'assistant')) continue;
  const conteudo = texto(item.content).slice(0, 2000);
  if (!conteudo) continue;
  const anterior = historico[historico.length - 1];
  if (anterior && anterior.role === item.role) {
    anterior.content += '\n' + conteudo;
  } else {
    historico.push({ role: item.role, content: conteudo });
  }
}
while (historico.length && historico[0].role !== 'user') historico.shift();
while (historico.length && historico[historico.length - 1].role !== 'assistant') historico.pop();

const promptDoSite = texto(corpo.prompt_sistema).slice(0, 30000);
const contexto = [texto(corpo.contexto_pagina), texto(corpo.taxas)].filter(Boolean).join('\n');
const sistema = promptDoSite || (contexto ? PROMPT_PADRAO + '\n\nContexto do site:\n' + contexto : PROMPT_PADRAO);

return {
  json: {
    valido: true,
    modo,
    pedido: {
      model: MODELO,
      max_tokens: 4096,
      system: sistema,
      messages: [...historico, { role: 'user', content: pergunta }],
      output_config: { effort: 'low', format: { type: 'json_schema', schema: SCHEMA_CHAT } }
    }
  }
};

const FONTE = 'Claude Haiku 5.5';
const pedido = $('Preparar Pedido ao Claude').item.json;
const resposta = $json;
const limpar = (valor) => (typeof valor === 'string' ? valor.replace(/\s+/g, ' ').trim() : '');

if (resposta.stop_reason === 'refusal') {
  if (pedido.modo === 'quiz') return { json: { usar_ia: true } };
  return {
    json: {
      titulo: 'Vamos falar de finanças?',
      resumo: 'Essa pergunta foge do que a GSA IA pode responder.',
      explicacao: 'Eu explico orçamento, dívidas, cartão de crédito, reserva de emergência e investimentos para iniciantes. Faça uma pergunta sobre um desses temas.',
      pontos_chave: [],
      exercicios: [],
      alerta: '',
      fonte_pesquisa: FONTE
    }
  };
}

const textoResposta = (Array.isArray(resposta.content) ? resposta.content : [])
  .filter((bloco) => bloco && bloco.type === 'text')
  .map((bloco) => bloco.text)
  .join('');

let dado = null;
if (resposta.stop_reason !== 'max_tokens') {
  try {
    dado = JSON.parse(textoResposta);
  } catch (erro) {
    dado = null;
  }
}
if (!dado || typeof dado !== 'object' || Array.isArray(dado)) {
  return { json: { usar_ia: true } };
}

if (pedido.modo === 'quiz') {
  const perguntas = (Array.isArray(dado.perguntas) ? dado.perguntas : [])
    .map((item) => {
      const opcoes = (Array.isArray(item.opcoes) ? item.opcoes : []).map(limpar).filter(Boolean).slice(0, 4);
      const correta = Number.isInteger(item.correta) && item.correta >= 0 && item.correta <= 3 ? item.correta : 0;
      return { pergunta: limpar(item.pergunta), opcoes, correta, explicacao: limpar(item.explicacao) };
    })
    .filter((item) => item.pergunta && item.opcoes.length === 4)
    .slice(0, pedido.quantidade || 8);
  return {
    json: {
      modo: 'quiz',
      titulo: limpar(dado.titulo) || 'Quiz: ' + pedido.modulo,
      descricao: limpar(dado.descricao) || 'Perguntas novas para praticar ' + pedido.modulo + '.',
      perguntas,
      fonte_pesquisa: FONTE
    }
  };
}

const card = {
  titulo: limpar(dado.titulo),
  resumo: limpar(dado.resumo),
  explicacao: limpar(dado.explicacao),
  pontos_chave: (Array.isArray(dado.pontos_chave) ? dado.pontos_chave : []).map(limpar).filter(Boolean).slice(0, 3),
  exercicios: [],
  alerta: limpar(dado.alerta),
  fonte_pesquisa: FONTE
};
if (!card.resumo && !card.explicacao) {
  return { json: { usar_ia: true } };
}
return { json: card };
